<script setup>
import{Head,Link,router}from'@inertiajs/vue3';import{ref}from'vue';import AppLayout from'../../../Layouts/AppLayout.vue';import ConfirmDialog from'../../../Components/ConfirmDialog.vue';defineProps({courses:Object,categories:Object});const purgeUrl=ref(null);const busy=ref(false);const purge=()=>{busy.value=true;router.delete(purgeUrl.value,{data:{confirmation:'PURGE'},onFinish:()=>{busy.value=false;purgeUrl.value=null}})}
</script>
<template><AppLayout><Head title="بایگانی"/><ConfirmDialog :open="!!purgeUrl" title="حذف دائمی" message="این عملیات قابل بازگشت نیست و همچنان به عبارت محافظتی نیاز دارد." phrase="PURGE" danger confirm-label="حذف دائمی" :busy="busy" @cancel="purgeUrl=null" @confirm="purge"/><section class="space-y-6 rounded-2xl border bg-white p-5"><div><h1 class="text-xl font-bold">بایگانی</h1><p class="text-sm text-slate-500">بازیابی امن است؛ حذف دائمی به واردکردن عبارت PURGE نیاز دارد.</p></div><div><h2 class="mb-3 font-bold">دوره‌های بایگانی‌شده</h2><div class="space-y-2"><div v-for="item in courses.data" :key="item.id" class="flex flex-wrap items-center justify-between gap-3 rounded-xl border p-3"><span>{{item.title}}</span><div class="flex gap-2"><Link :href="`/admin/archive/courses/${item.id}/restore`" method="post" as="button" class="text-teal-700">بازیابی</Link><button type="button" class="text-red-700" @click="purgeUrl=`/admin/purge/courses/${item.id}`">حذف دائمی</button></div></div><p v-if="!courses.data.length" class="rounded-xl border border-dashed p-5 text-center text-slate-500">دوره بایگانی‌شده‌ای وجود ندارد.</p></div></div><div><h2 class="mb-3 font-bold">دسته‌بندی‌های بایگانی‌شده</h2><div v-for="item in categories.data" :key="item.id" class="flex items-center justify-between rounded-xl border p-3"><span>{{item.name}}</span><Link :href="`/admin/archive/categories/${item.id}/restore`" method="post" as="button" class="text-teal-700">بازیابی</Link></div><p v-if="!categories.data.length" class="rounded-xl border border-dashed p-5 text-center text-slate-500">دسته‌بندی بایگانی‌شده‌ای وجود ندارد.</p></div></section></AppLayout></template>
